class StorageService {
  private getProjectMediaAdapters({ projectId }: { projectId: string }) {
    const mediaMetadataAdapter = new IndexedDBAdapter<MediaAssetData>({
      dbName: `${this.config.mediaDb}-${projectId}`,
      storeName: "media-metadata",
    });
    const mediaAssetsAdapter = new OPFSAdapter(`media-files-${projectId}`);
    return { mediaMetadataAdapter, mediaAssetsAdapter };
  }

  async saveMediaAsset({
    projectId,
    mediaAsset,
  }: {
    projectId: string;
    mediaAsset: MediaAsset;
  }): Promise<void> {
    const { mediaMetadataAdapter, mediaAssetsAdapter } =
      this.getProjectMediaAdapters({ projectId });

    const metadata: MediaAssetData = {
      id: mediaAsset.id,
      name: mediaAsset.name,
      type: mediaAsset.type,
      size: mediaAsset.file.size,
      width: mediaAsset.width,
      height: mediaAsset.height,
      thumbnailUrl: mediaAsset.thumbnailUrl,
    };

    try {
      await mediaAssetsAdapter.set({
        key: mediaAsset.id,
        value: mediaAsset.file,
      });
      await mediaMetadataAdapter.set({
        key: mediaAsset.id,
        value: metadata,
      });
    } catch (error) {
      try {
        await mediaAssetsAdapter.remove(mediaAsset.id);
      } catch {
        // Ignore cleanup failures so original error is preserved
      }
      if (this.isQuotaExceededError({ error })) {
        throw new StorageQuotaExceededError({
          requiredBytes: mediaAsset.file.size,
        });
      }
      throw error;
    }
  }
}

export const TICKS_PER_SECOND = 120_000;

declare const MediaTimeBrand: unique symbol;
export type MediaTime = number & { [MediaTimeBrand]?: never };

export function mediaTime({ ticks }: { ticks: number }): MediaTime {
  if (!Number.isInteger(ticks)) {
    throw new Error(`mediaTime: expected integer ticks, got ${ticks}`);
  }
  return ticks as MediaTime;
}

export function mediaTimeFromSeconds({ seconds }: { seconds: number }): MediaTime {
  return mediaTime({ ticks: Math.round(seconds * TICKS_PER_SECOND) });
}

export function mediaTimeToSeconds({ time }: { time: MediaTime }): number {
  return time / TICKS_PER_SECOND;
}

export function addMediaTime({ a, b }: { a: MediaTime; b: MediaTime }): MediaTime {
  return (a + b) as MediaTime;
}

export const useEditorStore = create<EditorState>((set, get) => ({
  project: null,
  isLoading: true,
  error: null,
  selectedElementIds: [],
  mediaUrls: {},
  isPlaying: false,

  loadProject: async (id) => {
    set({ isLoading: true, error: null });
    try {
      const result = await storageService.loadProject({ id });
      if (!result) {
        set({ isLoading: false, error: `Project "${id}" not found` });
        return;
      }
      const urls: Record<string, string> = {};
      const elements = result.project.scenes.tracks.elements;
      for (const el of elements) {
        if ('mediaId' in el && el.mediaId) {
          try {
            const asset = await storageService.loadMediaAsset({
              projectId: result.project.metadata.id,
              id: el.mediaId,
            });
            if (asset?.url) urls[el.mediaId] = asset.url;
          } catch {}
        }
      }
      set({ project: result.project, mediaUrls: urls, isLoading: false });
    } catch (err) {
      set({ isLoading: false, error: (err as Error).message });
    }
  },
}));

function useCheckStatus(promptId: string | null) {
  return useQuery<CheckStatusResponse>({
    queryKey: ['generate-status', promptId],
    queryFn: () => GenerateService.checkStatus(promptId!),
    enabled: !!promptId,
    refetchInterval: (query) => {
      const data = query.state.data;
      if (data?.status === 'completed' || data?.status === 'failed') return false;
      return 2000;
    },
  });
}

export function useGenerateVideo() {
  const generate = useGenerate();
  const [promptId, setPromptId] = useState<string | null>(null);
  const statusQuery = useCheckStatus(promptId);

  const handleGenerate = async (project: TProject) => {
    const { metadata } = buildMetadata(project);
    const images = await loadImages(project);
    const result = await generate.mutateAsync({ metadata, images });
    setPromptId(result.prompt_id);
  };

  return { handleGenerate, isGenerating: generate.isPending || !!promptId };
